    35  v_buff_size Unicode::getUtf8CharSequenceLength(v_char8 firstByte) {
    36
    37    if(firstByte < 128){
    38      return 1;
    39    }
    40
    41    if((firstByte | 192) != firstByte){
    42      return 0;
    43    }
    44
    45    if((firstByte | 32) != firstByte){
    46      return 2;
    47    } else if((firstByte | 16) != firstByte){
    48      return 3;
    49    } else if((firstByte | 8) != firstByte){
    50      return 4;
    51    } else if((firstByte | 4) != firstByte){
    52      return 5;
    53    } else if((firstByte | 2) != firstByte){
    54      return 6;
    55    } else {
    56      return 0;
    57    }
    58
    59  }
