    77  v_int32 Unicode::encodeUtf8Char(const char* sequence, v_buff_size& length){
    78    v_char8 byte = static_cast<v_char8>(sequence[0]);
    79    if(byte > 127){
    80      v_int32 code;
    81      if((byte | 32) != byte){
    82        length = 2;
    83        code =  ((31 & byte) << 6) | (sequence[1] & 63);
    84        return code;
    85      } else if((byte | 16) != byte){
    86        code = (15 & byte) << 12;
    87        length = 3;
    88      } else if((byte | 8) != byte){
    89        length = 4;
    90        v_int32 value = *(reinterpret_cast<p_int32>(const_cast<char*>(sequence)));
    91        code =  ((7 & byte) << 18)                  |
    92                (((value >> 24) & 0xFF) & 63)       |
    93                (((value >> 16) & 0xFF) & 63) << 6  |
    94                (((value >>  8) & 0xFF) & 63) << 12;
    95        return code;
    96      } else if((byte | 4) != byte){
    97        code = (3 & byte) << 24;
    98        length = 5;
    99      } else if((byte | 2) != byte){
   100        code = (1 & byte) << 30;
   101        length = 6;
   102      } else {
   103        return -1;
   104      }
   105
   106      v_char8 bitIndex = 0;
   107      for(v_buff_size i = length; i > 1; i--){
   108        code |= (sequence[i - 1] & 63) << bitIndex;
   109        bitIndex = static_cast<v_char8>(bitIndex + 6);
   110      }
   111      return code;
   112    } else {
   113      length = 1;
   114      return byte;
   115    }
   116  }
