   118  v_buff_size Unicode::decodeUtf8Char(v_int32 signed_code, p_char8 buffer) {
   119    v_uint32 code = static_cast<v_uint32>(signed_code);
   120    if(code >= 0x00000080 && code < 0x00000800){
   121      *(reinterpret_cast<p_int16>(buffer)) = static_cast<v_int16>(htons(((((code >> 6) & 31) | 192) << 8) | ((code & 63) | 128)));
   122      return 2;
   123    } else if(code >= 0x00000800 && code < 0x00010000){
   124      *(reinterpret_cast<p_int16>(buffer)) = static_cast<v_int16>(htons((((( code >> 12 ) & 15) | 224) << 8) |
   125                                    (((code >>  6 ) & 63) | 128)));
   126      buffer[2] = (code & 63) | 128;
   127      return 3;
   128    } else if(code >= 0x00010000 && code < 0x00200000){
   129      *(reinterpret_cast<p_int32>(buffer)) = static_cast<v_int32>(htonl(((((code >> 18 ) &  7) | 240) << 24) |
   130                                  ((((code >> 12 ) & 63) | 128) << 16) |
   131                                  ((((code >>  6 ) & 63) | 128) <<  8) |
   132                                   (( code         & 63) | 128)      ));
   133      return 4;
   134    } else if(code >= 0x00200000 && code < 0x04000000){
   135      *(reinterpret_cast<p_int32>(buffer)) = static_cast<v_int32>(htonl(((((code >> 24 ) &  3) | 248) << 24) |
   136                                  ((((code >> 18 ) & 63) | 128) << 16) |
   137                                  ((((code >> 12 ) & 63) | 128) <<  8) |
   138                                   (((code >>  6 ) & 63) | 128)));
   139      buffer[4] = (code & 63) | 128;
   140      return 5;
   141    } else if(code >= 0x04000000){
   142      *(reinterpret_cast<p_int32>(buffer)) = static_cast<v_int32>(htonl(((((code >> 30 ) &  1) | 252) << 24) |
   143                                  ((((code >> 24 ) & 63) | 128) << 16) |
   144                                  ((((code >> 18 ) & 63) | 128) <<  8) |
   145                                   (((code >> 12 ) & 63) | 128)));
   146      *(reinterpret_cast<p_int16>(&buffer[4])) = static_cast<v_int16>(htons(((((code >> 6 ) & 63) | 128) << 8) | (code & 63)));
   147      return 6;
   148    }
   149    buffer[0] = v_char8(code);
   150    return 1;
   151  }
