   153  void Unicode::codeToUtf16SurrogatePair(v_int32 code, v_int16& high, v_int16& low){
   154    code -= 0x010000;
   155    high = static_cast<v_int16>(0xD800 + ((code >> 10) & 1023));
   156    low = static_cast<v_int16>(0xDC00 + (code & 1023));
   157  }
   158
   159  v_int32 Unicode::utf16SurrogatePairToCode(v_int16 high, v_int16 low){
   160    return (((low - 0xDC00) & 1023) | (((high - 0xD800) & 1023) << 10)) + 0x010000;
   161  }
